    # קבל את הנתיב של הקובץ עצמו
    script_dir = os.path.dirname(os.path.abspath(__file__))
    # צור נתיב אבסולוטי לתיקיית cv
    resume_folder = os.path.join(script_dir, "../cv")
    
    resume_paths = [os.path.join(resume_folder, file) for file in os.listdir(resume_folder)]
    # resume_summaries = [summarize_document(resume_path,summarize_resume_text) for resume_path in resume_paths]
    try:  
        async with aiohttp.ClientSession() as session:
            for resume_path in resume_paths:
                # יצירת סיכום
                summarize = summarize_document(resume_path)  # ודא שזו פונקציה תקינה
                dropbox_path = f"/cv/{Path(resume_path).name}"
                print(dropbox_path)
                resume = {
                    'name': Path(resume_path).stem,
                    'user_id': user_id,
                    'url': get_shared_link(dropbox_path) ,
                    'summary': summarize,
                    'upload_date':str(date.today())
                }
                print("-----------------Uploading resume:", resume)
                
                # response=requests.post("http://127.0.0.1:8080/resumes", json={resume},headers={'Content-Type':'application/json','Content-Length':'Content-Length'}, verify=False)
                # response=await requests.post("https://127.0.0.1:8080/resumes", json={resume},headers={"Content-Type":"application/json"}, verify=False)

                # שליחת בקשה לשרת
                async with session.post(
                    "http://104.155.153.158:8080/resumes",
                    json=resume,
                    headers={"Content-Type": "application/json"},
                    ssl=False  # במידה ויש שגיאת SSL
                ) as response:
                    response_data = await response.json()
                    print("Response:", response_data)
                    
      
                
                # עדכון משתמש
                # update_user(user_id, response_data)
        
        return "Resumes added successfully"
    except Exception as e:
        print("Error occurred:", str(e))
        return f"Failed to add resumes: {e}"


